POST /dgidb/graphql#c159fd178b8d29bd.request_body:
{"query":"
query DgidbGeneDruggability($gene: String!, $first: Int!) {
  genes(names: [$gene], first: $first) {
    nodes {
      name
      geneCategories {
        name
      }
      interactions {
        drug {
          name
          approved
        }
        interactionScore
        interactionTypes {
          type
        }
        sources {
          sourceDbName
        }
      }
    }
  }
}
","variables":{"first":1,"gene":"EGFR"}}

POST /opentargets/graphql#34180b1b601253.request_body:
{"query":"
query TargetClinicalContext($ensemblId: String!, $size: Int!) {
  target(ensemblId: $ensemblId) {
    associatedDiseases(page: {index: 0, size: $size}) {
      rows {
        score
        disease {
          id
          name
        }
      }
    }
    drugAndClinicalCandidates {
      rows {
        drug {
          id
          name
        }
      }
    }
  }
}
","variables":{"ensemblId":"ENSG00000141736","size":5}}

